import { useState } from 'react'
import { MobileFormDrawer } from '@/components/ui/mobile-form-drawer'
import type { GearItem, GearCategory } from '@/types/database'
import { GearForm } from './GearForm'

interface GearFormData {
  description: string
  brand: string | null
  model: string | null
  item_type: GearCategory
  weight_g: number
  consumable: boolean
  notes: string | null
  price: number | null
  image_url: string | null
}

interface EditGearFormProps {
  item: GearItem
  onUpdate: (id: string, updates: Partial<Omit<GearItem, 'id' | 'user_id' | 'created_at' | 'updated_at'>>) => void
  onCancel: () => void
}

export function EditGearForm({ item, onUpdate, onCancel }: EditGearFormProps) {
  const [loading, setLoading] = useState(false)

  const handleSubmit = async (data: GearFormData) => {
    setLoading(true)
    try {
      await onUpdate(item.id, data)
    } finally {
      setLoading(false)
    }
  }

  const initialData = {
    description: item.description,
    brand: item.brand,
    model: item.model,
    item_type: item.item_type,
    weight_g: item.weight_g,
    consumable: item.consumable,
    price: item.price,
    notes: item.notes,
    image_url: item.image_url,
  }

  return (
    <MobileFormDrawer
      isOpen={true}
      onClose={onCancel}
      title="Edit Gear Item"
      primaryAction={{
        label: 'Update Item',
        onClick: () => {
          const form = document.querySelector('form[data-gear-form]') as HTMLFormElement
          if (form) {
            form.requestSubmit()
          }
        },
        loading
      }}
      secondaryAction={{
        label: 'Cancel',
        onClick: onCancel
      }}
    >
      <div className="p-6">
        <GearForm
          isEditing={true}
          initialData={initialData}
          onSubmit={handleSubmit}
          standalone={false}
        />
      </div>
    </MobileFormDrawer>
  )
}

import type { GearCategory } from '@/types/database'

// Standardized gear categories used throughout the app
export const GEAR_CATEGORIES: GearCategory[] = [
  'Shelter',
  'Sleep System', 
  'Cooking',
  'Water',
  'Clothing',
  'Electronics',
  'First Aid',
  'Navigation',
  'Other'
]

// Popular outdoor gear brands for intelligent CSV parsing and validation
export const GEAR_BRANDS: string[] = [
  'zpacks', 'hyperlite', 'gossamer', 'msr', 'big agnes', 'nemo',
  'patagonia', 'arcteryx', 'rei', 'black diamond', 'petzl',
  'osprey', 'gregory', 'deuter', 'jetboil', 'primus', 'sawyer',
  'katadyn', 'nalgene', 'hydrapak', 'smartwater', 'sea to summit',
  'ultimate direction', 'nathan', 'salomon', 'outdoor research',
  'therm-a-rest', 'klymit', 'western mountaineering', 'feathered friends',
  'enlightened equipment', 'katabatic', 'nunatak', 'cumulus',
  'montbell', 'rab', 'mammut', 'scarpa', 'la sportiva', 'salomon',
  'merrell', 'darn tough', 'smartwool', 'icebreaker', 'outdoor research',
  'mountain hardwear', 'marmot', 'the north face', 'columbia',
  'garmin', 'suunto', 'polar', 'casio', 'apple', 'anker',
  'goal zero', 'nitecore', 'fenix', 'olight', 'princeton tec'
]

// Category keywords for intelligent CSV parsing - maps common item descriptions to categories
export const CATEGORY_KEYWORDS: Record<string, string[]> = {
  'Shelter': ['shelter', 'tent', 'tarp', 'bivy', 'bivvy', 'footprint', 'stakes', 'guylines'],
  'Sleep System': ['sleep', 'sleeping', 'bag', 'pad', 'quilt', 'pillow', 'liner', 'blanket'],
  'Cooking': ['cook', 'cooking', 'stove', 'pot', 'mug', 'spork', 'spoon', 'fork', 'knife', 'bowl', 'cup', 'canister', 'fuel'],
  'Water': ['water', 'filter', 'bottle', 'hydration', 'reservoir', 'bladder', 'purification', 'tablets'],
  'Clothing': ['clothes', 'clothing', 'shirt', 'pants', 'jacket', 'hat', 'gloves', 'socks', 'underwear', 'base layer', 'rain gear'],
  'Electronics': ['electronics', 'phone', 'charger', 'headlamp', 'light', 'flashlight', 'battery', 'power bank', 'gps', 'watch'],
  'First Aid': ['first aid', 'medical', 'safety', 'emergency', 'bandage', 'medication', 'aspirin', 'tape'],
  'Navigation': ['navigation', 'map', 'compass', 'gps', 'guide', 'guidebook'],
  'Other': ['misc', 'miscellaneous', 'repair', 'kit', 'tool', 'duct tape', 'cord', 'rope']
}

// Flatten category keywords for simple string matching
export const ALL_CATEGORY_KEYWORDS: string[] = Object.values(CATEGORY_KEYWORDS).flat()

/**
 * Detect the most likely category for a given item name or description
 */
export function detectCategory(text: string): GearCategory {
  const lowerText = text.toLowerCase()

  // Check each category for keyword matches
  for (const [category, keywords] of Object.entries(CATEGORY_KEYWORDS)) {
    if (keywords.some(keyword => lowerText.includes(keyword))) {
      return category as GearCategory
    }
  }

  return 'Other'
}

/**
 * Detect if text contains a known brand name
 */
export function detectBrand(text: string): string | undefined {
  const lowerText = text.toLowerCase()

  const foundBrand = GEAR_BRANDS.find(brand => 
    lowerText.includes(brand.toLowerCase())
  )

  if (foundBrand) {
    // Proper case the brand name
    const words = foundBrand.toLowerCase().split(' ')
    return words.map(word => word.charAt(0).toUpperCase() + word.slice(1)).join(' ')
  }

  return undefined
}

