import { describe, it, expect, vi } from 'vitest'
import { render, screen, waitFor } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { AddGearForm } from './AddGearForm'
import React from 'react'

// Mock the auth context
vi.mock('@/contexts/AuthContext', () => ({
  useAuth: () => ({
    user: { id: 'test-user-id', email: 'test@example.com' },
    loading: false,
    signIn: vi.fn(),
    signUp: vi.fn(),
    signOut: vi.fn()
  }),
  AuthProvider: ({ children }: { children: React.ReactNode }) => <>{children}</>
}))

// Mock the image upload module
vi.mock('@/lib/imageUpload', () => ({
  uploadGearImage: vi.fn(),
  deleteGearImage: vi.fn()
}))

// Test wrapper for components
const TestWrapper = ({ children }: { children: React.ReactNode }) => {
  return <div>{children}</div>
}

describe('AddGearForm', () => {
  const mockOnAdd = vi.fn()

  beforeEach(() => {
    vi.clearAllMocks()
  })

  it('renders form with required fields', () => {
    render(
      <TestWrapper>
        <AddGearForm onAdd={mockOnAdd} />
      </TestWrapper>
    )

    expect(screen.getByLabelText(/item type/i)).toBeInTheDocument()
    expect(screen.getByLabelText(/description/i)).toBeInTheDocument()
    expect(screen.getByLabelText(/weight/i)).toBeInTheDocument()
    expect(screen.getByRole('button', { name: /add gear/i })).toBeInTheDocument()

    // Model is now in advanced section, not visible by default
    expect(screen.queryByLabelText(/model/i)).not.toBeInTheDocument()
  })

  it('shows required field indicators', () => {
    render(
      <TestWrapper>
        <AddGearForm onAdd={mockOnAdd} />
      </TestWrapper>
    )

    // Check for red asterisks on required fields - there should be multiple
    const asterisks = screen.getAllByText('*')
    expect(asterisks.length).toBeGreaterThanOrEqual(3) // Item Type, Description, and Weight are required

    // Check they have the correct styling (updated for new GearForm)
    asterisks.forEach(asterisk => {
      expect(asterisk).toHaveClass('text-red-500')
    })
  })

  it('handles form submission with valid data', async () => {
    const user = userEvent.setup()

    render(
      <TestWrapper>
        <AddGearForm onAdd={mockOnAdd} />
      </TestWrapper>
    )

    // Fill in required fields
    await user.type(screen.getByLabelText(/item type/i), 'Tent')
    await user.type(screen.getByLabelText(/description/i), 'Ultralight Tent')
    await user.type(screen.getByLabelText(/weight/i), '2.5')

    // Submit form
    await user.click(screen.getByRole('button', { name: /add gear/i }))

    await waitFor(() => {
      expect(mockOnAdd).toHaveBeenCalledWith({
        description: 'Ultralight Tent',
        brand: null,
        model: null,
        weight_g: 71, // 2.5oz = ~71g (smart weight conversion working)
        item_type: 'Tent',
        consumable: false,
        price: null,
        image_url: null,
        notes: null
      })
    })
  })

  it('validates required fields', async () => {
    const user = userEvent.setup()

    render(
      <TestWrapper>
        <AddGearForm onAdd={mockOnAdd} />
      </TestWrapper>
    )

    // Try to submit without filling required fields
    await user.click(screen.getByRole('button', { name: /add gear/i }))

    // Should not call onAdd
    expect(mockOnAdd).not.toHaveBeenCalled()
  })

  it('shows advanced fields when toggled', async () => {
    const user = userEvent.setup()

    render(
      <TestWrapper>
        <AddGearForm onAdd={mockOnAdd} />
      </TestWrapper>
    )

    // Advanced fields should not be visible initially
    expect(screen.queryByLabelText(/price/i)).not.toBeInTheDocument()

    // Click show advanced options
    await user.click(screen.getByText(/show advanced options/i))

    // Advanced fields should now be visible
    expect(screen.getByLabelText(/price/i)).toBeInTheDocument()
    expect(screen.getByText(/notes/i)).toBeInTheDocument()
  })

  it('allows manual entry of item type', async () => {
    const user = userEvent.setup()

    render(
      <TestWrapper>
        <AddGearForm onAdd={mockOnAdd} />
      </TestWrapper>
    )

    // Type a custom item type
    await user.type(screen.getByLabelText(/item type/i), 'Custom Shelter')

    await waitFor(() => {
      // Should display the entered text
      expect(screen.getByDisplayValue('Custom Shelter')).toBeInTheDocument()
    })
  })

  it('handles weight unit conversion', async () => {
    const user = userEvent.setup()

    render(
      <TestWrapper>
        <AddGearForm onAdd={mockOnAdd} />
      </TestWrapper>
    )

    // Enter weight value
    await user.type(screen.getByLabelText(/weight/i), '1')

    // The weight unit selector is now a SimpleSelect component which renders as a button
    // Look for the button that shows the current unit
    const weightUnitButton = screen.getByRole('button', { name: /oz/i })
    expect(weightUnitButton).toBeInTheDocument()

    // Fill in required fields and submit to test default conversion (oz)
    await user.type(screen.getByLabelText(/item type/i), 'Test Type')
    await user.type(screen.getByLabelText(/description/i), 'Test Item')
    await user.click(screen.getByRole('button', { name: /add gear/i }))

    await waitFor(() => {
      expect(mockOnAdd).toHaveBeenCalledWith(
        expect.objectContaining({
          weight_g: 28 // 1oz ≈ 28g (rounded to integer)
        })
      )
    })
  })

  describe('simplified mode', () => {
    it('hides advanced options in simplified mode', () => {
      render(
        <TestWrapper>
          <AddGearForm onAdd={mockOnAdd} simplified={true} />
        </TestWrapper>
      )

      expect(screen.queryByText(/show advanced options/i)).not.toBeInTheDocument()
    })

    it('shows different button text in simplified mode', () => {
      render(
        <TestWrapper>
          <AddGearForm onAdd={mockOnAdd} simplified={true} />
        </TestWrapper>
      )

      expect(screen.getByRole('button', { name: /add & continue/i })).toBeInTheDocument()
    })
  })
})

