async function fillGearForm(page, form, data) {
  // Wait for lazy-loaded form
  await page.waitForTimeout(1000)

  // Fill by specific input identifiers - using correct field IDs
  if (data.name) {
    const descriptionInput = form.locator('#description, input[placeholder*="Backpack" i]').first()
    await descriptionInput.waitFor({ state: 'visible' })
    await descriptionInput.fill(data.name)
  }

  if (data.weight) {
    const weightInput = form.locator('#weight, input[placeholder*="Weight" i]').first()
    await weightInput.waitFor({ state: 'visible' })
    await weightInput.fill(data.weight)
  }

  if (data.brand) {
    const brandInput = form.locator('#brand, input[placeholder*="Gossamer" i]').first()
    if (await brandInput.count() > 0) {
      await brandInput.fill(data.brand)
    }
  }

  if (data.category) {
    // Category might be a select or custom dropdown
    const categorySelect = form.locator('#item_type, select, button[role="combobox"]').first()
    if (await categorySelect.count() > 0) {
      await categorySelect.click()
      await page.waitForTimeout(500)
      // Look for option in dropdown or select
      const option = page.locator(`[role="option"]:has-text("${data.category}"), option:has-text("${data.category}")`)
      if (await option.count() > 0) {
        await option.first().click()
      }
    }
  }
}

