async function fillGearForm(page, form, data) {
  // Wait for lazy-loaded form
  await page.waitForTimeout(1000)

  // Fill item type first (now a required text input)
  if (data.itemType) {
    const itemTypeInput = form.locator('#item_type, input[placeholder*="Backpack" i]').first()
    await itemTypeInput.waitFor({ state: 'visible' })
    await itemTypeInput.fill(data.itemType)
  }

  // Fill description
  if (data.name) {
    const descriptionInput = form.locator('#description, input[placeholder*="Osprey" i]').first()
    await descriptionInput.waitFor({ state: 'visible' })
    await descriptionInput.fill(data.name)
  }

  // Fill weight
  if (data.weight) {
    const weightInput = form.locator('#weight, input[placeholder*="Weight" i]').first()
    await weightInput.waitFor({ state: 'visible' })
    await weightInput.fill(data.weight)
  }

  // Fill brand (in advanced section, may need to expand first)
  if (data.brand) {
    // Try to expand advanced options if brand field is not visible
    const brandInput = form.locator('#brand, input[placeholder*="Gossamer" i]').first()
    if (await brandInput.count() === 0) {
      // Look for "Show advanced options" button
      const advancedButton = form.locator('button:has-text("Show advanced options")')
      if (await advancedButton.count() > 0) {
        await advancedButton.click()
        await page.waitForTimeout(300)
      }
    }

    // Now try to fill the brand field
    const brandInputAfter = form.locator('#brand, input[placeholder*="Gossamer" i]').first()
    if (await brandInputAfter.count() > 0) {
      await brandInputAfter.fill(data.brand)
    }
  }
}

